const TARGET_GROUPS = {
  '919493561700-1545803250@g.us': 'MSK',
  '919930599976-1613022548@g.us': 'IPV',
  '120363427391049099@g.us':      'MoneyMavericks'
};

const payload = $input.first().json;
const body    = payload.body || payload;
const event   = body.event || '';
const data    = body.data || {};
const key     = data.key || {};
const msg     = data.message || {};

const groupJid  = key.remoteJid || '';
const isGroup   = groupJid.endsWith('@g.us');
const fromMe    = key.fromMe === true;
const msgId     = key.id || '';
const senderJid = data.participant || key.participant || '';
const pushName  = data.pushName || '';
const tsUnix    = data.messageTimestamp || Math.floor(Date.now()/1000);

// Message type detection
let msgType = 'text';
let mediaUrl = null;
if (msg.imageMessage) { msgType = 'image'; mediaUrl = msg.imageMessage.url || null; }
else if (msg.videoMessage) { msgType = 'video'; mediaUrl = msg.videoMessage.url || null; }
else if (msg.documentMessage) { msgType = 'document'; mediaUrl = msg.documentMessage.url || null; }
else if (msg.audioMessage) { msgType = 'audio'; mediaUrl = msg.audioMessage.url || null; }

// Text extraction (incl. captions and edit updates)
const editedText = msg.editedMessage && msg.editedMessage.message && (
  msg.editedMessage.message.conversation ||
  (msg.editedMessage.message.extendedTextMessage && msg.editedMessage.message.extendedTextMessage.text)
);
const text = (
  msg.conversation ||
  (msg.extendedTextMessage && msg.extendedTextMessage.text) ||
  (msg.imageMessage && msg.imageMessage.caption) ||
  (msg.videoMessage && msg.videoMessage.caption) ||
  editedText ||
  ''
).toString();

const isEdit = event === 'messages.update' || !!editedText;

if (!isGroup || fromMe) return [];
if (!TARGET_GROUPS[groupJid]) return [];

const nowIso  = new Date().toISOString();
const postedIso = new Date(tsUnix * 1000).toISOString();

return [{
  json: {
    message_id:   msgId,
    group_jid:    groupJid,
    source_group: TARGET_GROUPS[groupJid],
    sender_jid:   senderJid,
    push_name:    pushName,
    body:         text,
    message_type: msgType,
    media_url:    mediaUrl,
    is_edit:      isEdit,
    posted_at:    postedIso,
    received_at:  nowIso,
    has_text:     !!text.trim()
  }
}];

// COST-CONTROLLED EXTRACTOR: regex first, cheap filters before LLM
const PATTERNS = [
  /(?:(?<trade_type>POSITIONAL\s+TRADE|INTRADAY\s+TRADE|BTST\s+TRADE|SWING\s+TRADE)\s*[\r\n]+)?\s*(?<stock>[A-Z][A-Z0-9&.\- ]{1,40}?)\s*[\r\n]+\s*Looks\s+Good\s+ABOVE\s+(?<entry>\d+(?:\.\d+)?)\s*[\r\n]+\s*SL\s+(?<sl>\d+(?:\.\d+)?)\s*[\r\n]+\s*Targets?\s+(?<targets>[\d.\-+\s]+?)(?<points>\s*points?\s+from\s+entry)?(?:\s*[\r\n]|$)/is,
  /(?<stock>[A-Z][A-Z0-9&.\- ]{1,40}?)\s*[\r\n]+.*?(?:Buy|BUY|buy)\s*(?:above|@|at)?\s*(?<entry>\d+(?:\.\d+)?).*?(?:SL|Stop\s*Loss|stoploss)[:\s]*(?<sl>\d+(?:\.\d+)?).*?(?:Target|TGT|Tgt|target)s?[:\s]*(?<targets>[\d.\s,+\-]+)/is
];

// Skip patterns (never send to LLM - saves cost)
const SKIP_RE = /🔥|target\s+hit|booked|profit\s+booked|good\s+morning|good\s+night|thank|congrat|welcome|👍|😀|😂|❤️|🙏/i;
const PNL_RE  = /\+\d+%|\-\d+%|profit\s+of|loss\s+of|return\s+of/i;
const LINK_RE = /^https?:\/\/|youtube\.com|youtu\.be|t\.me/i;

// Signal-likely heuristic: message must have BOTH a number AND a signal keyword
const NUMBER_RE  = /\d+/;
const KEYWORD_RE = /(?:buy|sell|target|sl|stoploss|stop\s*loss|tgt|entry|above|below|positional|intraday|swing|btst)/i;

const MAX_LEN_FOR_LLM = 2000;

const input = $input.first().json;
const body  = (input.body || '').toString();
const len   = body.length;

// Try regex first (0 cost)
for (const re of PATTERNS) {
  const m = body.match(re);
  if (!m || !m.groups) continue;
  const g = m.groups;
  const entry = parseFloat(g.entry);
  const sl    = parseFloat(g.sl);
  if (isNaN(entry) || isNaN(sl)) continue;
  const rawTargets = (g.targets || '').replace(/[+,\s]+/g,'-').replace(/-+/g,'-').replace(/^-|-$/g,'').split('-').filter(Boolean);
  let targets = rawTargets.map(Number).filter(n => !isNaN(n));
  const mode = g.points ? 'points_from_entry' : 'absolute';
  if (mode === 'points_from_entry') targets = targets.map(t => Number((entry + t).toFixed(2)));
  return [{
    json: {
      ...input,
      trade_type:     (g.trade_type || '').toUpperCase().trim() || null,
      stock_name_raw: g.stock.replace(/\s+/g,' ').trim(),
      entry_price:    entry,
      stop_loss:      sl,
      targets,
      targets_mode:   mode,
      extractor:      'regex',
      confidence:     0.9,
      extractor_result: 'ok'
    }
  }];
}

// Regex missed - decide whether to spend LLM $
const llmEnabled = ($env.LLM_ENABLED || 'true').toLowerCase() !== 'false';
let skipReason = null;
if (!llmEnabled)                skipReason = 'llm_disabled';
else if (len > MAX_LEN_FOR_LLM) skipReason = 'too_long';
else if (len < 20)              skipReason = 'too_short';
else if (SKIP_RE.test(body))    skipReason = 'skip_pattern';
else if (PNL_RE.test(body))     skipReason = 'pnl_update';
else if (LINK_RE.test(body))    skipReason = 'link_only';
else if (!NUMBER_RE.test(body)) skipReason = 'no_number';
else if (!KEYWORD_RE.test(body))skipReason = 'no_keyword';

if (skipReason) {
  return [{ json: { ...input, extractor_result: 'skipped_' + skipReason } }];
}

return [{ json: { ...input, extractor_result: 'regex_miss' } }];

