const original = $('Regex extract').first().json;
const llmResp  = $input.first().json;

// Cost per 1M tokens (USD) for allowed models
const PRICING = {
  'google/gemini-2.0-flash-exp:free': { in: 0,      out: 0 },
  'google/gemini-flash-1.5-8b':       { in: 0.038,  out: 0.15 },
  'google/gemini-flash-1.5':          { in: 0.075,  out: 0.30 }
};

const model  = llmResp.model || 'google/gemini-2.0-flash-exp:free';
const usage  = llmResp.usage || {};
const inTok  = usage.prompt_tokens || 0;
const outTok = usage.completion_tokens || 0;
const price  = PRICING[model] || { in: 0.1, out: 0.4 };
const costUsd = ((inTok * price.in) + (outTok * price.out)) / 1_000_000;

let parsed = null;
let rawJson = null;
try {
  const content = llmResp.choices && llmResp.choices[0] && llmResp.choices[0].message && llmResp.choices[0].message.content;
  if (content) {
    rawJson = content;
    const clean = content.replace(/```json\s*|```/g, '').trim();
    parsed = JSON.parse(clean);
  }
} catch (e) {
  return [{ json: { ...original, llm_error: e.message, llm_raw: rawJson, skip_insert: true, llm_model: model, llm_in_tokens: inTok, llm_out_tokens: outTok, llm_cost_usd: costUsd } }];
}

const common = { llm_model: model, llm_in_tokens: inTok, llm_out_tokens: outTok, llm_cost_usd: costUsd, llm_raw: rawJson };

if (!parsed || !parsed.is_signal) {
  return [{ json: { ...original, ...common, extractor: 'llm', skip_insert: true } }];
}

let targets = Array.isArray(parsed.targets) ? parsed.targets.map(Number).filter(n => !isNaN(n)) : [];
if (parsed.targets_mode === 'points_from_entry' && parsed.entry_price) {
  targets = targets.map(t => Number((parsed.entry_price + t).toFixed(2)));
}

return [{
  json: {
    ...original,
    ...common,
    trade_type:     parsed.trade_type || null,
    stock_name_raw: parsed.stock_name || null,
    entry_price:    parsed.entry_price || null,
    stop_loss:      parsed.stop_loss || null,
    targets,
    targets_mode:   parsed.targets_mode || 'absolute',
    extractor:      'llm',
    confidence:     Math.min(0.75, (parsed.confidence || 0.6)),
    skip_insert:    false
  }
}];

const idx  = $itemIndex;
const prev = $('Merge regex+LLM').all()[idx].json;
const sym  = $input.all()[idx] ? $input.all()[idx].json : {};
return [{ json: { ...prev, nse_symbol: sym.nse_symbol || null } }];

const s = $input.first().json;
if (!s || !s.id) return [];

const targetsArr = ($('Merge symbol back').first().json.targets || []);
const symbol   = s.nse_symbol || s.stock_name_raw || 'UNKNOWN';
const extractor = (s.extractor || '').toUpperCase();
const conf     = s.confidence ? Number(s.confidence).toFixed(2) : 'n/a';

const lines = [
  '🚨 *Signal captured*',
  `Source: ${s.source_group}`,
  `Stock:  ${symbol}`,
  `Entry:  ₹${s.entry_price}`,
  `SL:     ₹${s.stop_loss}`,
  `Tgts:   ${targetsArr.length ? targetsArr.join(', ') : '—'}`,
  `Src:    ${extractor} (conf ${conf})`
];
if (!s.nse_symbol) lines.push('⚠️  Symbol not resolved — manual review');

return [{ json: { alert_text: lines.join('\n'), signal_id: s.id } }];
